def transform(grid):
    n = len(grid)
    out = [row[:] for row in grid]

    row_values = []
    row_mode = True
    for row in grid:
        colors = set(row) - {0}
        if len(colors) > 1:
            row_mode = False
            break
        row_values.append(next(iter(colors)) if colors else 0)

    if row_mode:
        known = {r: value for r, value in enumerate(row_values) if value}
        period = next(p for p in range(1, n + 1)
                      if all(len({value for r, value in known.items() if r % p == residue}) <= 1
                             for residue in range(p))
                      and all(any(r % p == residue for r in known) for residue in range(p)))
        sequence = {residue: next(value for r, value in known.items() if r % period == residue)
                    for residue in range(period)}
        for r in range(n):
            if row_values[r] == 0:
                out[r] = [sequence[r % period]] * n
        return out

    for key in (lambda r, c: (c - r) % n, lambda r, c: (r + c) % n):
        clues = {}
        conflict = False
        for r in range(n):
            for c in range(n):
                value = grid[r][c]
                if value:
                    diagonal = key(r, c)
                    if diagonal in clues and clues[diagonal] != value:
                        conflict = True
                    clues[diagonal] = value
        if conflict or not clues:
            continue
        for period in range(1, n + 1):
            compatible = all(len({value for diagonal, value in clues.items()
                                  if diagonal % period == residue}) <= 1
                             for residue in range(period))
            complete = all(any(diagonal % period == residue for diagonal in clues)
                           for residue in range(period))
            if compatible and complete:
                sequence = {residue: next(value for diagonal, value in clues.items()
                                          if diagonal % period == residue)
                            for residue in range(period)}
                for r in range(n):
                    for c in range(n):
                        if grid[r][c] == 0:
                            out[r][c] = sequence[key(r, c) % period]
                return out
    return out

